function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
    window.aivicNotify?.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify?.success(message);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    // 業務ロジックでの期間バリデーション
    if (validateComparisonPeriod && startDate && endDate) {
      try {
        const isValid = validateComparisonPeriod(startDate, endDate);
        if (!isValid) {
          showError('指定された期間は無効です');
          return false;
        }
      } catch (error) {
        showError('期間バリデーションエラー: ' + error.message);
        return false;
      }
    }

    return true;
  }

  // 需要予測データを取得・分析
  async function getDemandForecast(productId, storeId, startDate, endDate) {
    try {
      // 売上データを収集
      const salesData = collectSalesData ? await collectSalesData(productId, storeId, startDate, endDate) : [];

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : salesData;

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData ? filterValidProductData(productSalesData) : productSalesData;

      // 天候データを収集
      const weatherData = collectWeatherData ? await collectWeatherData(startDate, endDate) : [];

      // イベントデータを収集
      const eventData = collectEventData ? await collectEventData(startDate, endDate) : [];

      // 季節データを収集
      const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

      // 相関分析
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(validProductData, weatherData);
      }
      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(validProductData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlationResults.seasonal = analyzeCorrelationSalesSeason(validProductData, seasonalData);
      }

      // 過去データとの比較
      let historicalComparison = null;
      if (compareWithHistoricalData) {
        try {
          historicalComparison = await compareWithHistoricalData(validProductData, startDate, endDate);
        } catch (error) {
          // 代替比較データを探す
          if (findAlternativeComparisonData) {
            historicalComparison = await findAlternativeComparisonData(validProductData, startDate, endDate);
          }
        }
      }

      // 予測需要を計算（簡易的な実装）
      const baseAmount = validProductData.reduce((sum, item) => sum + (item.amount || 0), 0);
      const weatherFactor = correlationResults.weather?.correlation || 1;
      const eventFactor = correlationResults.event?.correlation || 1;
      const seasonalFactor = correlationResults.seasonal?.correlation || 1;
      const historicalFactor = historicalComparison?.growthRate || 1;

      const predictedDemand = Math.round(baseAmount * weatherFactor * eventFactor * seasonalFactor * historicalFactor);

      return {
        predictedDemand: Math.max(0, predictedDemand),
        correlationResults,
        historicalComparison,
        confidence: Math.min(100, Math.max(0, (weatherFactor + eventFactor + seasonalFactor) * 33.33))
      };
    } catch (error) {
      console.error('需要予測エラー:', error);
      return {
        predictedDemand: 0,
        correlationResults: {},
        historicalComparison: null,
        confidence: 0
      };
    }
  }

  // 商品テーブル再描画
  async function renderProducts(products) {
    const tbody = container.querySelector('#product-tbody');

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" class="muted">該当する商品が見つかりませんでした</td></tr>';
      return;
    }

    const storeId = container.querySelector('#store-select')?.value;
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    const productRows = await Promise.all(products.map(async (product) => {
      const currentStock = Math.floor(Math.random() * 100) + 10; // 模擬在庫数

      // 業務ロジックを使用して需要予測を取得
      const forecastResult = await getDemandForecast(product.id, storeId, startDate, endDate);
      const predictedDemand = forecastResult.predictedDemand || Math.floor(Math.random() * 50) + 5;
      const recommendedOrder = Math.max(0, predictedDemand - currentStock + 10); // 推奨発注量

      return `
        <tr data-id="${product.id}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.id}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${currentStock}</td>
          <td>${predictedDemand}</td>
          <td>${recommendedOrder}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 5px;">
              <button class="adjust-btn" data-action="decrease" data-product-id="${product.id}">-</button>
              <input type="number" class="quantity-input" id="qty-${product.id}" 
                     value="${recommendedOrder}" min="0" max="999999999"
                     data-product-id="${product.id}">
              <button class="adjust-btn" data-action="increase" data-product-id="${product.id}">+</button>
            </div>
          </td>
          <td>
            <input type="text" class="reason-input" id="reason-${product.id}" 
                   placeholder="発注理由" maxlength="500">
          </td>
          <td>
            <button class="action-btn secondary order-btn" data-product-id="${product.id}">発注</button>
          </td>
        </tr>
      `;
    }));

    tbody.innerHTML = productRows.join('');

    // 数量調整ボタンのイベントリスナーを追加
    tbody.querySelectorAll('.adjust-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const productId = e.target.dataset.productId;
        const action = e.target.dataset.action;
        const delta = action === 'increase' ? 1 : -1;
        adjustQuantity(productId, delta);
      });
    });

    // 個別発注ボタンのイベントリスナーを追加
    tbody.querySelectorAll('.order-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const productId = e.target.dataset.productId;
        handleSingleOrder(productId);
      });
    });
  }

  // 数量調整関数
  function adjustQuantity(productId, delta) {
    const input = container.querySelector(`#qty-${productId}`);
    if (input) {
      const currentValue = parseInt(input.value) || 0;
      const newValue = Math.max(0, Math.min(999999999, currentValue + delta));
      input.value = newValue;
    }
  }

  // 個別発注処理
  async function handleSingleOrder(productId) {
    try {
      const quantityInput = container.querySelector(`#qty-${productId}`);
      const reasonInput = container.querySelector(`#reason-${productId}`);

      if (!quantityInput) {
        showError('発注数量が取得できません');
        return;
      }

      const quantity = parseInt(quantityInput.value) || 0;
      const reason = reasonInput?.value || '';

      if (quantity <= 0) {
        showError('発注数量は1以上を入力してください');
        return;
      }

      const storeId = container.querySelector('#store-select')?.value;
      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      // 発注データを保存
      const orderData = {
        店舗ID: storeId,
        商品ID: productId,
        発注数量: quantity,
        発注理由: reason,
        発注日時: new Date().toISOString(),
        ステータス: '発注済み'
      };

      await window.aivicApi.save(tables[ORDER_TABLE], orderData);
      showSuccess('発注が完了しました');

      // 発注履歴を更新
      loadOrderHistory();

    } catch (error) {
      console.error('発注エラー:', error);
      showError('発注処理中にエラーが発生しました: ' + error.message);
    }
  }

  // 一括発注処理
  async function handleBulkOrder() {
    try {
      const checkboxes = container.querySelectorAll('.product-checkbox:checked');

      if (checkboxes.length === 0) {
        showError('発注する商品を選択してください');
        return;
      }

      const storeId = container.querySelector('#store-select')?.value;
      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      const orders = [];
      let hasError = false;

      for (const checkbox of checkboxes) {
        const productId = checkbox.dataset.productId;
        const quantityInput = container.querySelector(`#qty-${productId}`);
        const reasonInput = container.querySelector(`#reason-${productId}`);

        const quantity = parseInt(quantityInput?.value) || 0;
        const reason = reasonInput?.value || '';

        if (quantity <= 0) {
          showError(`商品ID ${productId} の発注数量は1以上を入力してください`);
          hasError = true;
          break;
        }

        orders.push({
          店舗ID: storeId,
          商品ID: productId,
          発注数量: quantity,
          発注理由: reason,
          発注日時: new Date().toISOString(),
          ステータス: '発注済み'
        });
      }

      if (hasError) return;

      // 一括保存
      for (const orderData of orders) {
        await window.aivicApi.save(tables[ORDER_TABLE], orderData);
      }

      showSuccess(`${orders.length}件の発注が完了しました`);

      // チェックボックスをクリア
      checkboxes.forEach(cb => cb.checked = false);

      // 発注履歴を更新
      loadOrderHistory();

    } catch (error) {
      console.error('一括発注エラー:', error);
      showError('一括発注処理中にエラーが発生しました: ' + error.message);
    }
  }

  // 店舗選択肢を読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(tables[STORES_TABLE]);
      const storeSelect = container.querySelector('#store-select');

      if (storeSelect) {
        storeSelect.innerHTML = '<option value="">店舗を選択</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
      }
    } catch (error) {
      console.error('店舗データ読み込みエラー:', error);
      showError('店舗データの読み込みに失敗しました');
    }
  }

  // 商品検索
  async function searchProducts() {
    try {
      if (!validateDateRange()) return;

      const storeId = container.querySelector('#store-select')?.value;
      const productCode = container.querySelector('#product-code')?.value;
      const productName = container.querySelector('#product-name')?.value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      let products = await window.aivicApi.list(tables[PRODUCTS_TABLE]);

      // フィルタリング
      if (productCode) {
        products = products.filter(p => p.商品コード && p.商品コード.includes(productCode));
      }
      if (productName) {
        products = products.filter(p => p.商品名 && p.商品名.includes(productName));
      }

      // 業務ロジックでの商品データフィルタリング
      if (filterValidProductData) {
        products = filterValidProductData(products);
      }

      currentProducts = products;
      await renderProducts(products);

    } catch (error) {
      console.error('商品検索エラー:', error);
      showError('商品検索中にエラーが発生しました: ' + error.message);
    }
  }

  // 発注履歴を読み込み
  async function loadOrderHistory() {
    try {
      const orders = await window.aivicApi.list(tables[ORDER_TABLE]);
      const tbody = container.querySelector('#order-history-tbody');

      if (!tbody) return;

      if (!orders || orders.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="muted">発注履歴がありません</td></tr>';
        return;
      }

      // 最新の発注から表示
      const sortedOrders = orders.sort((a, b) => new Date(b.発注日時) - new Date(a.発注日時));

      tbody.innerHTML = sortedOrders.map(order => `
        <tr>
          <td>${new Date(order.発注日時).toLocaleString()}</td>
          <td>${order.商品ID}</td>
          <td>${order.発注数量}</td>
          <td>${order.発注理由 || ''}</td>
          <td><span class="status ${order.ステータス === '発注済み' ? 'success' : 'pending'}">${order.ステータス}</span></td>
          <td>
            <button class="action-btn danger cancel-btn" data-order-id="${order.id}" 
                    ${order.ステータス !== '発注済み' ? 'disabled' : ''}>キャンセル</button>
          </td>
        </tr>
      `).join('');

      // キャンセルボタンのイベントリスナーを追加
      tbody.querySelectorAll('.cancel-btn:not([disabled])').forEach(btn => {
        btn.addEventListener('click', (e) => {
          const orderId = e.target.dataset.orderId;
          handleCancelOrder(orderId);
        });
      });

    } catch (error) {
      console.error('発注履歴読み込みエラー:', error);
      showError('発注履歴の読み込みに失敗しました');
    }
  }

  // 発注キャンセル処理
  async function handleCancelOrder(orderId) {
    try {
      if (!confirm('この発注をキャンセルしますか？')) return;

      await window.aivicApi.update(tables[ORDER_TABLE], orderId, { ステータス: 'キャンセル済み' });
      showSuccess('発注をキャンセルしました');
      loadOrderHistory();

    } catch (error) {
      console.error('発注キャンセルエラー:', error);
      showError('発注キャンセル中にエラーが発生しました: ' + error.message);
    }
  }

  // 全選択/全解除
  function handleSelectAll() {
    const selectAllCheckbox = container.querySelector('#select-all');
    const productCheckboxes = container.querySelectorAll('.product-checkbox');

    if (selectAllCheckbox) {
      productCheckboxes.forEach(cb => {
        cb.checked = selectAllCheckbox.checked;
      });
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#search-btn');
    if (searchBtn) {
      searchBtn.addEventListener('click', searchProducts);
    }

    // 一括発注ボタン
    const bulkOrderBtn = container.querySelector('#bulk-order-btn');
    if (bulkOrderBtn) {
      bulkOrderBtn.addEventListener('click', handleBulkOrder);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', handleSelectAll);
    }

    // 日付入力のバリデーション
    const dateInputs = container.querySelectorAll('#date-start, #date-end');
    dateInputs.forEach(input => {
      input.addEventListener('change', validateDateRange);
    });
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadOrderHistory();
      setupEventListeners();

      // デフォルト日付を設定
      const today = new Date();
      const startDate = new Date(today.getFullYear(), today.getMonth(), 1);
      const endDate = new Date(today.getFullYear(), today.getMonth() + 1, 0);

      const startInput = container.querySelector('#date-start');
      const endInput = container.querySelector('#date-end');

      if (startInput) startInput.value = startDate.toISOString().split('T')[0];
      if (endInput) endInput.value = endDate.toISOString().split('T')[0];

    } catch (error) {
      console.error('初期化エラー:', error);
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
